{
  "schemaVersion": "0.2",
  "slug": "inline-alert",
  "name": "InlineAlert",
  "status": "experimental",
  "purpose": "Displays a contextual message within a form or page.",
  "scenarios": [
    "Show a form-level error",
    "Explain a disabled field",
    "Highlight a tip"
  ],
  "props": {
    "children": {
      "type": "node",
      "required": true,
      "description": "Alert message."
    },
    "status": {
      "type": "enum",
      "required": false,
      "description": "Semantic tone.",
      "values": [
        "info",
        "success",
        "warning",
        "error"
      ],
      "default": "info"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "status",
      "values": [
        "info",
        "success",
        "warning",
        "error"
      ],
      "default": "info",
      "description": "Semantic tone."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Alert rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "field",
      "page",
      "card"
    ],
    "allowedChildren": [
      "text"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for non-contextual global alerts.",
    "Do not hide the alert without a way to read it again."
  ],
  "a11y": {
    "role": "status",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "Contents are the alert message.",
    "wcag": [
      "4.1.3"
    ]
  },
  "responsive": {
    "strategy": "Full width within parent.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Full width.",
      "large": "Full width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only; accent on inline-start.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "inline-alert",
    "states": [
      "info",
      "success",
      "warning",
      "error"
    ],
    "intents": [
      "flag-field-error"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface InlineAlertProps {
  children: ReactNode
  status?: 'info' | 'success' | 'warning' | 'error'
  className?: string
}

export function InlineAlert({ children, status = 'info', className }: InlineAlertProps) {
  const classes = ['cu-inline-alert', 'cu-inline-alert--' + status, className].filter(Boolean).join(' ')
  return <div className={classes} data-ai-role="inline-alert" data-ai-intent="flag-field-error" data-ai-state={status} role="status">{children}</div>
}

.cu-inline-alert {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border-radius: var(--cu-radius-md);
  border-inline-start: 4px solid var(--cu-color-border-default);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font-size: 0.875rem;
}

.cu-inline-alert--info {
  border-inline-start-color: var(--cu-color-palette-brand);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
}

.cu-inline-alert--success {
  border-inline-start-color: #16a34a;
  background: color-mix(in srgb, #16a34a 10%, var(--cu-color-background-default));
}

.cu-inline-alert--warning {
  border-inline-start-color: #f59e0b;
  background: color-mix(in srgb, #f59e0b 10%, var(--cu-color-background-default));
}

.cu-inline-alert--error {
  border-inline-start-color: #dc2626;
  background: color-mix(in srgb, #dc2626 10%, var(--cu-color-background-default));
}
